'use strict';
const E=TradeEngine,$=id=>document.getElementById(id),money=v=>Number.isFinite(v)?'$'+v.toFixed(2):'—',num=v=>Number.isFinite(v)?v.toFixed(2):'—';
let snapshot,chart,candles,markerApi,active='BMNR',barData=[],option=null,plannedQty=0,priceLines=[],pendingText='';
const series={};
function toast(t){$('toast').textContent=t;$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',4000);}
async function copy(t){pendingText=t;try{await navigator.clipboard.writeText(t);toast('Copied. Paste into ChatGPT to continue.');}catch{$('copy-text').value=t;$('copy-dialog').showModal();$('copy-text').select();}}
function textRow(label,value){const row=document.createElement('div'),l=document.createElement('span'),v=document.createElement('strong');l.textContent=label;v.textContent=value;row.append(l,v);return row;}
function makeChart(){if(!globalThis.LightweightCharts){$('chart-error').hidden=false;$('chart-error').textContent='Chart library could not load. Reload this page. The ticket panel remains available.';return;}chart=LightweightCharts.createChart($('chart'),{autoSize:true,layout:{background:{color:'#0d1624'},textColor:'#9caec6',fontSize:12,attributionLogo:true},grid:{vertLines:{color:'#172437'},horzLines:{color:'#172437'}},rightPriceScale:{borderColor:'#26354a'},timeScale:{timeVisible:true,secondsVisible:false,tickMarkFormatter:t=>new Intl.DateTimeFormat('en-US',{timeZone:'America/New_York',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date(t*1000)),borderColor:'#26354a'},localization:{timeFormatter:t=>E.et(t*1000)},crosshair:{mode:0}});candles=chart.addSeries(LightweightCharts.CandlestickSeries,{upColor:'#59d6a5',downColor:'#ff8395',borderVisible:false,wickUpColor:'#59d6a5',wickDownColor:'#ff8395'});for(const [key,color] of Object.entries({fast:'#62dedb',slow:'#ffcb72',vwap:'#bfa1ff'}))series[key]=chart.addSeries(LightweightCharts.LineSeries,{color,lineWidth:2,priceLineVisible:false,lastValueVisible:false,title:key==='fast'?'EMA 9':key==='slow'?'EMA 21':'VWAP'});series.rsi=chart.addSeries(LightweightCharts.LineSeries,{color:'#bfa1ff',lineWidth:2,title:'RSI 14',priceLineVisible:false,lastValueVisible:true},1);series.rsi.createPriceLine({price:70,color:'#785366',lineWidth:1,lineStyle:2,axisLabelVisible:true,title:'70'});series.rsi.createPriceLine({price:30,color:'#42695f',lineWidth:1,lineStyle:2,axisLabelVisible:true,title:'30'});markerApi=LightweightCharts.createSeriesMarkers(candles,[]);chart.subscribeCrosshairMove(p=>{const c=p.seriesData.get(candles);if(c)$('chart-caption').textContent=`${E.et(Number(p.time)*1000)} ET · O ${money(c.open)}   H ${money(c.high)}   L ${money(c.low)}   C ${money(c.close)} · Underlying stock prices`;});}
function loadSnapshot(s){E.validate(s);snapshot=s;const names=Object.keys(s.bars);if(!names.length)throw Error('Snapshot has no symbols.');if(!names.includes(active))active=names[0];$('symbol').replaceChildren(...names.map(n=>{const o=document.createElement('option');o.value=o.textContent=n;return o;}));$('symbol').value=active;$('market').textContent='Dated snapshot · '+(s.market?.is_open?'captured during market hours':'captured outside market hours');$('capture').textContent='Captured '+E.et(s.capturedAt)+' ET';$('fill-scope').textContent=s.fillScope??'Imported broker fills only; not a complete position history.';renderSymbol();}
function renderSymbol(){active=$('symbol').value;barData=E.regular(snapshot.bars[active]).filter(x=>Date.parse(x.timestamp)+900000<=Date.parse(snapshot.capturedAt));const last=barData.at(-1),l=E.levels(barData);$('title').textContent=active+'  '+money(last?.close);$('chart-caption').textContent=last?`Last completed bar: ${E.et(last.timestamp)} ET · IEX feed · scroll to zoom, drag to pan · options fills mark time on the underlying chart`:'No completed regular-session bars.';const i=E.indicators(barData),data=barData.map(b=>({...b,time:Date.parse(b.timestamp)/1000}));if(chart){candles.setData(data);for(const key of ['fast','slow','vwap','rsi'])series[key].setData(data.flatMap((b,n)=>Number.isFinite(i[key][n])?[{time:b.time,value:i[key][n]}]:[]));chart.timeScale().fitContent();}for(const [id,v] of Object.entries({'bias':l?.bias??'Insufficient data','rsi-value':num(l?.rsi),'vwap-value':money(l?.vwap),'atr-value':money(l?.atr)}))$(id).textContent=v;$('bias').className=l?.bias==='Bullish'?'positive':l?.bias==='Bearish'?'negative':'';const g=snapshot.gex?.[active];$('levels').replaceChildren();if(l){for(const [label,v] of [['Long breakout',l.high],['Long stock stop / target',money(l.longStop)+' / '+money(l.longTarget)],['Short breakout',l.low],['Short stock stop / target',money(l.shortStop)+' / '+money(l.shortTarget)],['Opening range high / low',money(l.orbHigh)+' / '+money(l.orbLow)]])$('levels').append(textRow(label,typeof v==='number'?money(v):v));}if(g){for(const [label,key] of [['Call wall','call_wall'],['Put wall','put_wall'],['Gamma flip','gamma_flip']])$('levels').append(textRow(label,money(Number(g[key]))));$('levels').append(textRow('UW snapshot',`${g.date} · ${g.source??'vol'}`));}if(!l&&!g)$('levels').textContent='No levels available.';$('stock-entry').value=last?.close.toFixed(2)??'';$('stock-stop').value=l?Math.max(.01,last.close-1.5*l.atr).toFixed(2):'';renderFills();renderOptions();applyOverlays();}
function renderFills(){const fills=snapshot.fills.filter(f=>f.underlying===active);$('executions').replaceChildren();if(!fills.length){$('executions').textContent='No imported fills for this symbol.';return;}for(const f of fills){const row=document.createElement('div');row.className='fill';const title=document.createElement('b'),detail=document.createElement('span');title.textContent=`${f.side.toUpperCase()} ${f.quantity} ${f.asset==='option'?`${money(f.strike)} ${f.type} · ${f.expiry}`:'shares'}`;title.className=f.side==='buy'?'positive':'negative';detail.textContent=`Filled ${money(f.price)} ${f.asset==='option'?'premium':'per share'} · ${E.et(f.time)} ET`;row.append(title,detail);$('executions').append(row);}}
function applyOverlays(){if(!chart)return;series.fast.applyOptions({visible:$('ema').checked});series.slow.applyOptions({visible:$('ema').checked});series.vwap.applyOptions({visible:$('vwap').checked});series.rsi.applyOptions({visible:$('rsi').checked});priceLines.forEach(l=>candles.removePriceLine(l));priceLines=[];const add=(price,title,color)=>{if(Number.isFinite(price))priceLines.push(candles.createPriceLine({price,title,color,lineWidth:1,lineStyle:2,axisLabelVisible:true}));};const l=E.levels(barData),g=snapshot.gex?.[active];if($('orb').checked&&l){add(l.orbHigh,'ORB high','#5ba6ff');add(l.orbLow,'ORB low','#5ba6ff');}if($('gex').checked&&g){add(Number(g.call_wall),'UW call wall · '+g.date,'#59d6a5');add(Number(g.put_wall),'UW put wall · '+g.date,'#ff8395');add(Number(g.gamma_flip),'UW gamma flip','#ffcb72');}const markers=[];if($('fills').checked){for(const f of snapshot.fills.filter(f=>f.underlying===active)){const t=Date.parse(f.time);const b=barData.find(b=>t>=Date.parse(b.timestamp)&&t<Date.parse(b.timestamp)+900000);if(b)markers.push({time:Date.parse(b.timestamp)/1000,position:f.side==='buy'?'belowBar':'aboveBar',color:f.side==='buy'?'#59d6a5':'#ff8395',shape:f.side==='buy'?'arrowUp':'arrowDown',text:`${f.side.toUpperCase()} ${f.quantity} ${f.asset==='option'?f.type+' premium ':''}${money(f.price)}`});}}markerApi.setMarkers(markers.sort((a,b)=>a.time-b.time));}
function renderOptions(){const [lo,hi]=$('dte').value.split('-').map(Number),day=E.session(new Date().toISOString()).day;const options=snapshot.contracts.filter(c=>{const d=Math.round((Date.parse(c.expiry+'T00:00:00Z')-Date.parse(day+'T00:00:00Z'))/86400000);return c.underlying===active&&c.type===$('direction').value&&d>=lo&&d<=hi;}).sort((a,b)=>a.expiry.localeCompare(b.expiry)||a.strike-b.strike);const prior=$('contract').value;$('contract').replaceChildren(...options.map(c=>{const o=document.createElement('option');o.value=c.symbol;o.textContent=`${c.expiry} · $${c.strike} ${c.type} · ask ${money(c.ask)}`;return o;}));if(!options.length){const o=document.createElement('option');o.textContent='No contracts in this snapshot';o.value='';$('contract').append(o);}else{const reference=options.find(c=>c.symbol===prior)??options.reduce((a,b)=>Math.abs(b.strike-barData.at(-1)?.close)<Math.abs(a.strike-barData.at(-1)?.close)?b:a);$('contract').value=reference.symbol;}renderTicket();}
function renderTicket(){const isOption=$('asset').value==='option';$('option-controls').hidden=!isOption;$('stock-controls').hidden=isOption;option=snapshot.contracts.find(c=>c.symbol===$('contract').value)??null;const capital=Number($('capital').value),riskPct=Number($('risk').value),budget=Number($('budget').value);plannedQty=0;let detail='',status='';$('quote').replaceChildren();if(isOption){if(option){const c=option;for(const [k,v] of [['Bid / ask',money(c.bid)+' / '+money(c.ask)],['Delta',num(c.delta)],['IV',Number.isFinite(c.iv)?(c.iv*100).toFixed(1)+'%':'—'],['Theta / day',num(c.theta)]])$('quote').append(textRow(k,v));const validQuote=c.bid!==null&&c.ask!==null&&c.bid>0&&c.ask>=c.bid;plannedQty=validQuote?E.sizeOption({capital,riskPct,budget,buyingPower:null,ask:c.ask,multiplier:c.multiplier}):0;detail=`Full-premium risk: ${money(plannedQty*(c.ask??0)*c.multiplier)}. Budget: ${money(budget)}. Risk allowance: ${money(capital*riskPct/100)}.`;status=`${c.feed??'Unknown feed'} · Quote ${c.quoteTime?E.et(c.quoteTime)+' ET':'time unavailable'}. Broker quote, liquidity, buying power and contract eligibility must be rechecked.`;if(!validQuote)status='No valid two-sided quote. Planning size is zero. '+status;if(!plannedQty)detail+=' Zero fits these limits; do not force a contract.';}else{detail='Refresh with ChatGPT to import the exact option chain.';status='No imported contract selected.';}}else{const entry=Number($('stock-entry').value),stop=Number($('stock-stop').value);if([capital,riskPct,budget,entry,stop].every(Number.isFinite)&&capital>=0&&budget>=0&&riskPct>0&&riskPct<=100&&entry>stop&&stop>0)plannedQty=Math.max(0,Math.floor(Math.min(capital*riskPct/100/(entry-stop),budget/entry,capital/entry)));detail=`Planned spend: ${money(plannedQty*entry)} · modeled loss at stop: ${money(plannedQty*(entry-stop))}. Stops do not guarantee a maximum loss.`;status='Stock prices are from the dated snapshot. Verify current quote, buying power and stop placement before any order.';}$('size').textContent=plannedQty+(isOption?' contracts':' shares');$('sizing-detail').textContent=detail;$('ticket-status').textContent=status;$('ticket').disabled=isOption&&!option;}
function ticketText(){const isOption=$('asset').value==='option',prefix=`Use @RobinAI to REVIEW ONLY this proposed trade. Do not place, modify or cancel any order. Verify the current accessible account via get_accounts; the last verified account was ${snapshot.account?.label??'not selected'}. Do not assume account balance or buying power.\n\n`;const data=isOption?`${active}: long ${option.type}, strike $${option.strike}, expiration ${option.expiry}, OCC ${option.symbol}. Snapshot ask ${option.ask}; quote time ${option.quoteTime}; feed ${option.feed}. Preliminary size ${plannedQty} contracts. Full premium at risk. Resolve the exact Robinhood contract; do not treat the OCC symbol as the Robinhood option ID.`:`${active}: BUY shares. Preliminary size ${plannedQty} shares, planned entry $${$('stock-entry').value}, stock stop-reference $${$('stock-stop').value}. The stop is not an order.`;return prefix+data+`\nPlanning capital $${$('capital').value} (user-entered, not verified); maximum spend $${$('budget').value}; risk allowance ${$('risk').value}%. Snapshot captured ${snapshot.capturedAt}.\nRefresh bid/ask, quote timestamp, market session, spreads, buying power, contract multiplier, option approval and eligibility. For options also inspect Greeks, IV, volume, open interest and available expirations. Recompute quantity against the full premium risk cap and available funds. If zero contracts fit, say NO TRADE. Stale or indicative quotes cannot authorize execution. Present the exact current ticket for user approval. Do not reuse these historical prices as a live limit order.`;}
function refreshText(){return `Refresh my Hanif Trade Desk snapshot using @Alpaca @Unusual Whales @RobinAI and my GitHub repository ElOmair/trading-agents-scanner. This is research only; do not submit orders.\nPull 15-minute bars for ${Object.keys(snapshot.bars).join(', ')}, disclose the available feed, exclude unfinished candles, refresh UW GEX levels with source and timestamp, and retrieve actual option chains with bid/ask, quote timestamps, Greeks and multiplier. Refresh recent fills from the previously verified account ${snapshot.account?.label??'(ask me to choose)'} after confirming access. Do not assume buying power.\nUpdate the existing Hanif Trade Desk Site (do not create a duplicate) or produce a schemaVersion 1 snapshot JSON that its Import snapshot control accepts. The current schema is available via Export snapshot and in the GitHub trade-desk folder. Distinguish historical snapshots from live data. This webpage cannot call chat connectors on its own.`;}
function download(){const blob=new Blob([JSON.stringify(snapshot,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='trade-desk-snapshot.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function registerTools(){const ctx=document.modelContext;if(!ctx?.registerTool)return;for(const t of [{name:'import_trade_snapshot',description:'Validate and load a broker/market snapshot into the visible chart workspace. Does not trade or persist data.',inputSchema:{type:'object',properties:{snapshot:{type:'object'}},required:['snapshot'],additionalProperties:false},execute:input=>{loadSnapshot(input.snapshot);return {symbols:Object.keys(snapshot.bars),capturedAt:snapshot.capturedAt};},annotations:{readOnlyHint:false,untrustedContentHint:true}},{name:'select_trade_symbol',description:'Select an imported symbol on the chart.',inputSchema:{type:'object',properties:{symbol:{type:'string'}},required:['symbol'],additionalProperties:false},execute:input=>{if(!snapshot.bars[input.symbol])throw Error('Symbol not imported.');$('symbol').value=input.symbol;renderSymbol();return {symbol:active};},annotations:{readOnlyHint:false}},{name:'read_review_ticket',description:'Read the currently staged research ticket. Does not approve or execute any trade.',inputSchema:{type:'object',properties:{},additionalProperties:false},execute:()=>{if($('asset').value==='option'&&!option)throw Error('No contract selected.');return {text:ticketText(),quantity:plannedQty,execution:false};},annotations:{readOnlyHint:true}}]){try{Promise.resolve(ctx.registerTool(t)).catch(()=>{});}catch{}}}
async function main(){makeChart();try{const r=await fetch('snapshot.json',{cache:'no-store'});if(!r.ok)throw Error('Snapshot unavailable. Import a snapshot to begin.');loadSnapshot(await r.json());}catch(e){$('title').textContent='Import a snapshot to begin';$('market').textContent='No market data loaded';toast(e.message);}$('symbol').onchange=renderSymbol;for(const id of ['ema','vwap','rsi','orb','gex','fills'])$(id).onchange=applyOverlays;$('fit').onclick=()=>chart?.timeScale().fitContent();for(const id of ['direction','dte'])$(id).onchange=renderOptions;for(const id of ['asset','capital','risk','budget','contract','stock-entry','stock-stop'])$(id).oninput=()=>snapshot&&renderTicket();$('ticket').onclick=()=>copy(ticketText());$('refresh').onclick=()=>snapshot?copy(refreshText()):toast('Import a snapshot first.');$('export').onclick=()=>snapshot?download():toast('No snapshot loaded.');$('import').onclick=()=>$('file').click();$('file').onchange=async()=>{try{const f=$('file').files[0];if(!f)return;if(f.size>10*1024*1024)throw Error('Snapshot must be under 10 MB.');const s=JSON.parse(await f.text());E.validate(s);loadSnapshot(s);toast('Snapshot imported for this session.');}catch(e){toast(e.message);}$('file').value='';};$('close-dialog').onclick=()=>$('copy-dialog').close();registerTools();}
main();
